    this.src = src;
    this.start = performance.now() / 1000;
    this.time_limit = limit;
    this.parse(src);
  }

  parse(src: string): void {
    this.pos = parse_space(src, 0, true);
    while (this.pos < src.length) {
      this.parse_rule(src);
    }

