567	  *__iterate_over_pointers__(
568	    pointers: Iterable<GraphPointer>,
569	  ): Generator<[UnresolvedRule, GraphPointer[]]> {
570	    // Keyed by rule identity: the reference's `Rule.__hash__` is `id(self)`, so
