580	      if (seen_rule === undefined) {
581	        seen_rule = [pointer];
582	        seen_rules.set(rule, seen_rule);
583	      }
584	      seen_rule.push(pointer);
585	    }
586	
587	    yield* seen_rules.entries();
588	  }
